package com.handy.parakeet;
import android.Manifest;import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.media.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.Arrays;
public class Main2Activity extends Activity{TextView s,t;Button b;volatile boolean rec;Thread th;static{System.loadLibrary("transcribe");}static native String nativeLoadModel(String p);static native String nativeStart();static native String nativeFeed(float[]a);static native String nativeFinish();static native void nativeClose();
public void onCreate(Bundle x){super.onCreate(x);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(32,48,32,32);TextView h=new TextView(this);h.setText("Parakeet Transcriber");h.setTextSize(26);l.addView(h);Button p=new Button(this);p.setText("Choose Parakeet GGUF model");l.addView(p);b=new Button(this);b.setText("Hold to speak");b.setEnabled(false);l.addView(b);s=new TextView(this);s.setText("Choose a .gguf model.");l.addView(s);t=new TextView(this);t.setTextSize(18);l.addView(t);p.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/octet-stream");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,7);});b.setOnTouchListener((v,e)->{if(e.getAction()==0){start();return true;}if(e.getAction()==1||e.getAction()==3){stop();return true;}return true;});setContentView(l);}
protected void onActivityResult(int r,int c,Intent d){if(r!=7||c!=RESULT_OK)return;try{Uri u=d.getData();File f=new File(getFilesDir(),"model.gguf");InputStream i=getContentResolver().openInputStream(u);OutputStream o=new FileOutputStream(f);byte[]z=new byte[65536];int n;while((n=i.read(z))>0)o.write(z,0,n);i.close();o.close();s.setText("Loading model…");new Thread(()->{String e=nativeLoadModel(f.getAbsolutePath());runOnUiThread(()->{s.setText(e==null?"Model loaded. Hold to speak.":e);b.setEnabled(e==null);});}).start();}catch(Exception e){s.setText(e.toString());}}
void start(){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},8);return;}String e=nativeStart();if(e!=null){s.setText(e);return;}rec=true;b.setText("Listening… release to transcribe");th=new Thread(()->{int m=AudioRecord.getMinBufferSize(16000,16,2);AudioRecord a=new AudioRecord(1,16000,16,2,Math.max(m,4096)*2);short[]q=new short[2048];float[]f=new float[2048];a.startRecording();while(rec){int n=a.read(q,0,q.length);if(n>0){for(int j=0;j<n;j++)f[j]=q[j]/32768f;nativeFeed(Arrays.copyOf(f,n));}}a.stop();a.release();});th.start();}
void stop(){if(!rec)return;rec=false;b.setText("Hold to speak");new Thread(()->{try{th.join();}catch(Exception e){}String x=nativeFinish();runOnUiThread(()->{t.setText(x==null?"":x);s.setText("Ready");});}).start();}protected void onDestroy(){rec=false;nativeClose();super.onDestroy();}}
